(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["lb"] = {"ui":{"skip":"Zum Inhalt sprangen","back":"← Zréck bei AI-gile","lang.button":"Sprooch: {name}","lang.dialog":"Wiel eng Sprooch","lang.search":"Sproochen sichen","lang.none":"Keng Sprooch passt","lang.notYet":"{name} ass nach net iwwersat","theme.aria":"Tëscht hellem an donkelem Design wiesselen","theme.toLight":"Op hellt Design wiesselen","theme.toDark":"Op donkelt Design wiesselen","words.underline":"Dës Wierder op der Säit ënnersträichen","words.underlineHelp":"Gëff mat der Maus iwwer e gepunktent Wuert oder tipp drop, fir ze gesinn, wat et heescht.","index.title":"AI-gile: däin KI-Entwécklerteam, op enger Tafel","index.description":"AI-gile ass eng Kanban-Tafel fir KI-Programméierteams. Si schaffen, während s du schléifs; fir dech bleift ee kuerze Stapel: wat ze decidéieren, ze testen an unzehuelen ass.","hero.logoAlt":"AI-gile-Tafelsymbol","hero.h1.html":"Däin KI-Entwécklerteam, op enger&nbsp;Tafel.","hero.alpha":"🐣 Zouene Pre-Alpha","hero.alphaTitle":"Fréi an onfäerdeg: merci, dass du et ausprobéiers!","hero.lede":"Si bauen, während s du schléifs. Du wuess op a fënns ee kuerze Stapel: e puer Froen, e puer Saachen zum Testen, een oder zwee violett Diamanten. Klicken, unhuelen, zeréck bei däi Kaffi.","dl.windows":"Windows-App","dl.browser":"Am Browser lafen","dl.soon":"Geschwënn","dl.notify":"🔔 Sot mer Bescheed, wann et opgeet","dl.notifySmall":"Alpha oder Beta","hero.secondary":"Agile, awer d'Team brauch ni e Stand-up-Kaffi. (Si maache Stand-ups trotzdem.)","pitch.h2":"AI-gile a sou villen Wierder, wéi s du wëlls","pitch.lede":"Wiel eng Längt, vun engem Wuert bis 144. All Längt ass eng eege Beschreiwung, geschriwwe fir déi Gréisst. Zéi de Schieber oder benotz d'Pfeiltaste.","pitch.rangeLabel":"Längt a Wierder","pitch.dice":"🎲 eng aner Versioun","pitch.words.one":"{n} Wuert","pitch.words.other":"{n} Wierder","pitch.letters.one":"{n} Buschtaf","pitch.letters.other":"{n} Buschtawen","pitch.chars.one":"{n} Zeechen","pitch.chars.other":"{n} Zeechen","count.line.html.one":"{n} Kaart elo op der Tafel","count.line.html.other":"{n} Kaarten elo op der Tafel","features.aria":"Wat et mécht","f.pile.h":"Ee Stapel fir dech","f.pile.html":"<b>Fir dech</b> hält alles, wat op dech waart, vun alle Projeten: Froen, Saachen zum Testen, Aufgaben, déi nëmmen e Mënsch ka maachen. Deng Schlaang seet, wat als Nächst kënnt a wéi laang et dauert.","f.sleep.h":"Teams, déi schaffen, während s du schléifs","f.sleep.p":"All Projet huet e Lead an e Team vun KI-Agenten. Kommentéier eng Kaart, an d'Team erwächt, mécht d'Aarbecht an hëlt se zeréck mat Schrëtt, déi och e midde Mënsch verfollege kann.","f.tester.h":"Fir d'éischt kontrolléiert en KI-Tester","f.tester.p":"Ier eppes bei dech kënnt, geet en Tester d'Schrëtt an enger Kopie vun der App duerch a weist, wat en gesinn huet, mat engem Screenshot. Bliedert duerch déi, déi bestanen hunn, an huel se mat engem Klick un.","f.proof.h":"Beweiser, net Verspriechen","f.proof.p":"All Iwwergab weist, wat geännert gouf: d'Dateien, den Ënnerscheed, d'Screenshoten. Keng Apps méi opmaachen, fir ze kucken, ob et fäerdeg ass.","f.chat.h":"Schwätz mat dengen Leads","f.chat.p":"Eng Leescht wéi bei Discord: een Ikon pro Projet, violett Diamanten fir dat, wat dech brauch. Schreif engem Lead eng Iddi; en mécht Kaarten an e Plang dorausser, mat engem ✅ Go-Knäppchen.","f.tidy.h":"Hält sech selwer opgeraumt","f.tidy.p":"Verwandte Kaarten ginn zu enger zesummegeluecht, duerchenee Titele gi gefléckt, an e Token-Check hält de Code schlank. Manner, wat een wiesselt, manner, un dat een denke muss.","f.private.h":"Deng, op dengem Computer","f.private.li1":"D'Tafel leeft op dengem eegene Computer an äntwert nëmmen dir.","f.private.li2":"Privat Noriichten tëscht Leit sinn Enn-zu-Enn verschlësselt.","f.private.li3":"Keng Konten, keng Tracker, keng Cookien.","f.lang.h":"A denger Sprooch","f.lang.p":"Iwwer 120 Sproochen, vum Hollännesche, Walisesche a Japanesche bis zu Piroten, Yoda a Klingonesch, mat engem séieren Zeréckwiessel op Englesch fir d'Entwécklerwierder.","tl.aria":"Zäitleescht vum éischte Gespréich bis zur Roadmap","tl.h2":"Vum éischte Chat bis zu deem, wat kënnt","tl.lede":"Richteg Datumer an Auerzäiten, an denger eegener Zäitzon. Nom Haut ass et de Plang, ouni versprachent Datumer.","tl.today":"Haut","tl.planned":"geplangt","tl.cards.one":"{n} Kaart","tl.cards.other":"{n} Kaarten","join.h2":"Maach mat","join.lede":"AI-gile gëtt vun engem klenge Mënsch a ganz villen gedëlleg Agenten gebaut. Fir de Moment ass et privat, an enger zouener Alpha mat Frënn. Wëlls du et probéieren, wann et opgeet?","join.btn":"Interessi umellen","join.small":"Mir schreiwen dir eng E-Mail, soss näischt","footer.tag":"AI-gile. Keng Tracker, keng Cookien, kee Stand-up-Kaffi.","footer.licence":"Geschäftslizenz","footer.status":"Status","footer.privacy":"Wat mir behalen","form.sending":"Gëtt geschéckt…","form.failed":"Dat huet net geklappt: probéier et méi spéit nach eng Kéier.","form.offline":"AI-gile war net z'erreechen: probéier et méi spéit nach eng Kéier.","form.keep":"Mir benotzen dat nëmmen, fir dir ze äntweren, an dann läsche mir et. Keng Tracker, keng Cookien.","form.keepLink":"Wat mir behalen","interest.title":"AI-gile: sot mer Bescheed, wann d'Alpha opgeet","interest.description":"Looss deng E-Mail do, fir ze héieren, wann d'zouene Alpha oder Beta vun AI-gile opgeet.","interest.h1":"🔔 Sot mer Bescheed, wann et opgeet","interest.lede":"AI-gile ass an der zouener Pre-Alpha. Looss deng E-Mail do, a mir schreiwe ee Mol, wann et e Plaz fir dech gëtt.","interest.email":"Deng E-Mail","interest.which":"Wéi een Test?","interest.alpha":"Zouen Alpha: fréi, rau, vill Ännerungen","interest.beta":"Beta: méi roueg, méi spéit","interest.both":"Egal wéi eng, déi als Éischt kënnt","interest.submit":"Setz mech op d'Lëscht","interest.thanks":"Merci! Du bass op der Lëscht.","licence.title":"AI-gile: Geschäftslizenz","licence.description":"Benotz du AI-gile an dengem Geschäft? Frot eng gratis Geschäftslizenz un.","licence.h1":"📜 Geschäftslizenz","licence.lede":"Benotz du AI-gile op der Aarbecht? Sot eis, wien s du bass a wat s du méchs. Wann et eppes Gutts bewierkt, ass d'Lizenz gratis.","licence.company":"Firma","licence.website":"Websäit","licence.what":"Wat s du méchs","licence.how":"Wéi et der Welt hëlleft","licence.email":"E-Mail","licence.submit":"Umellen","licence.thanks":"Merci! Mir äntweren per E-Mail.","status.title":"AI-gile-Status","status.h1":"AI-gile-Status","status.quiet":"Alles roueg","status.intro":"Funktionéiert AI-gile grad? Dës Säit kontrolléiert all 5 Minutten d'Websäit, d'Deele vun Tafelen, d'Uriff an den Download.","status.up":"Funktionéiert (huet an {ms} ms geäntwert)","status.slow":"Huet op déi lescht Kontroll net geäntwert, probéiert et nach eng Kéier","status.down":"Ausgefall: huet op déi lescht zwou Kontrollen net geäntwert","status.svc.web":"Websäit","status.svc.web.offers":"Dës Säit: wat AI-gile ass, an den Interessi-Formulaire","status.svc.boards":"Tafelen deelen","status.svc.boards.offers":"Ëffentlech Tafelen, Messagen tëscht Frënn an Invitatiounen","status.svc.calls":"Uriff","status.svc.calls.offers":"Stëmm, Video an Ecran deelen an AI-gile","status.svc.download":"Download","status.svc.download.offers":"De Windows-Installateur an Invitatiounslinken","status.checking":"Gëtt kontrolléiert…","status.offline":"De Statusservice ass de Moment net z'erreechen (probéiert et nach eng Kéier)","status.updated":"aktualiséiert {ago}","status.justNow":"grad elo","status.min":"viru {n} Min.","status.hours":"viru {n} Std.","status.days":"viru {n} Deeg","privacy.title":"AI-gile: wat mir behalen","privacy.h1":"Wat mir behalen","privacy.lede":"Kuerz gesot: nëmmen dat, wat s du eis schécks, an net laang.","privacy.only":"Nëmmen dat, wat s du eis schécks: wat s du an e Formulaire agëss, wéi deng E-Mail. Soss näischt iwwer dech.","privacy.sealed":"Et gëtt versigelt, sou datt eise Server et net liese kann: an dengem Browser, ier et fortgeet (op engem méi alen Browser, soubal et ukënnt). Nëmmen eis eege Tafel kann et opmaachen.","privacy.server":"Et gëtt vum Server geläscht, soubal et op eiser Tafel ukënnt. Alles, wat no 30 Deeg nach do ass, gëtt souwisou geläscht.","privacy.board":"Mir halen et nëmmen esou laang op eiser Tafel, bis mir dir geäntwert hunn, dann läsche mir et och do.","privacy.none":"Keng Tracker, keng Cookien, keng Analysen.","privacy.local":"Deng Sprooch an deng Wiel tëscht hell an donkel bleiwen an dengem eegene Browser. Si ginn eis ni geschéckt.","privacy.ask":"Wëlls du, datt et méi fréi ewech ass? Äntwer op eis E-Mail a so eis et.","live.h2":"Kuck zou, wéi et gebaut gëtt, live","live.caption":"All Kaart ass verstoppt: du gesäis d'Form vun der Aarbecht, net d'Wierder.","live.watching.one":"live: {n} kuckt","live.watching.other":"live: {n} kucken","live.last.now":"Lescht Kaart grad elo geréckelt","live.last.min.one":"Lescht Kaart viru {n} Minutt geréckelt","live.last.min.other":"Lescht Kaart viru {n} Minutte geréckelt","live.last.hour.one":"Lescht Kaart viru {n} Stonn geréckelt","live.last.hour.other":"Lescht Kaart viru {n} Stonne geréckelt","live.last.day.one":"Lescht Kaart viru {n} Dag geréckelt","live.last.day.other":"Lescht Kaart viru {n} Deeg geréckelt","live.offline":"D'Live-Board mécht eng kleng Paus. Kuck geschwë nees vir.","live.cols":"Backlog|Ze maachen|Amgaang|Team kontrolléiert|Fir dech zum Testen|Fir d'Team|Fäerdeg"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboteren.","Delegéiert."]},{"n":2,"texts":["Roboteren schaffen.","Agenten, organiséiert.","Iddien, gebaut."]},{"n":3,"texts":["Kanban fir Roboteren.","Iddie ginn Funktiounen.","Gratis Agent-Kanban."]},{"n":5,"texts":["Kanban-Tafel, vun Agenten ugedriwwen.","Du schreifs Kaarten. Agenten bauen.","Gratis, lokal, getest, e bësse domm."]},{"n":8,"texts":["Eng gratis Kanban-Tafel, op där KI-Agenten schaffen.","Schreif eng Iddi. Agenten bauen se. Du hëlls un.","Agile fir ee Mënsch a vill gedëlleg Roboteren."]},{"n":13,"texts":["Eng Kanban-Tafel op dengem Computer, där KI-Agenten d'Kaarten ofschaffen, während s du de Chef bleifs.","Schreif eng Iddi. E Team vun Agenten baut se. En Tester kontrolléiert se. Du seess Jo.","Keng Konten, keng Tracker: eng Tafel, e puer Roboteren an du, deen d'Say huet."]},{"n":21,"texts":["AI-gile ass eng Kanban-Tafel fir d'Zesummenaarbecht mat KI-Programméieragenten. Si huelen d'Kaarten, du testes se a hëlls se un.","All Projet kritt e Lead an e Team vun KI-Agenten. Kommentéier iergendeng Kaart, an d'Team mécht sech un d'Aarbecht.","Eng gratis, perséinlech To-do-Tafel, déi op dengem eegene Computer leeft. D'Aarbechter sinn Roboteren. Deen, dee Jo seet, bass du."]},{"n":34,"texts":["Du leess Iddie op eng Tafel. E Team vun KI-Agenten mécht se zu funktionéierende Funktiounen, testet se a gëtt se der zeréck, mat Schrëtt zum Probéieren. Näischt zielt als fäerdeg, bis du et seess.","AI-gile ass eng hausgemaachte Kanban-Tafel, déi de Rich mat vill Hëllef vun den Agenten gebaut huet, déi se elo verwalt. Si ass gratis, leeft op dengem Computer a gëtt mat Frënn gedeelt, net verkaaft.","Stell der eng ganz normal Kanban-Tafel vir, mat Kolonnen vu Backlog bis Done, nëmmen datt d'Kaarten vun KI-Agenten opgeholl ginn. Si bréngen Neiegkeeten, froen no, wa se festhänken, a waarden ëmmer op däin Daum no uewen."]},{"n":55,"texts":["AI-gile ass eng Kanban-Tafel, wou d'Team aus KI-Agenten besteet. All Projet huet e Lead, deen d'Aarbecht plangt, an Hëllefer, déi se bauen. Wann eng Funktioun prett ass, probéiert en KI-Tester se aus a mécht e Screenshot, duerno landet se an dengem Stapel. Huel se un, oder kommentéier, an d'Team schafft se nei.","Et huet ugefaange mat enger Persoun, déi vill KI-Programméiersessiounen op eemol am Bléck wollt behalen, a gouf zu enger richteger Tafel. Si leeft op dengem Computer, brauch kee Kont a läit keng Tracker un. Si ass gratis fir Frënn a fir all, deen nei giereg ass. Si ass nach net fäerdeg, also erwaart rau Kanten an heiansdo eng Iwwerraschung.","Hei ass déi éierlech Versioun. Du muss nach ëmmer d'Iddie hunn, an du muss d'Resultater nach ëmmer kontrolléieren. Wat AI-gile mécht, ass alles dertëscht: et hält d'Kaarten an der Rei, erweckt dee richtegen Agent, wann s du kommentéiers, weist genee, wat geännert gouf, a sammelt alles an engem kuerze Stapel fir dech."]},{"n":89,"texts":["AI-gile ass eng gratis Kanban-Tafel, déi s du op dengem eegene Computer lafe léiss. Amplaz vu Leit huet all Projet e Team vun KI-Agenten: e Lead, deen deng Iddien a Kaarten an e Plang ëmwandelt, an Hëllefer, déi d'Kaarten no Prioritéit ofschaffen. Wann eppes gebaut ass, geet en KI-Tester d'Testschrëtt duerch a weist dir, wat en gesinn huet. Dunn waart et an engem Stapel mam Numm Fir dech. Du hëlls et un, oder du kommentéiers, an d'Team probéiert et nach eng Kéier. Näischt kënnt ouni dech bei Done.","E puer Funktiounen, un déi s du vläicht net denks. Eng Nuechtwuecht hält d'Kolonn Ze maachen gefëllt, während s du schléifs, a wielt Kaarten aus, déi keng Äntwert vun dir brauchen. En Token-Zieler weist, wéi vill d'Agenten haut an dës Woch gebraucht hunn, an de No Token Mode seet hinnen, si sollen oppassen. Du kanns Frënn schreiwen, a privat Noriichte sinn Enn-zu-Enn verschlësselt. D'Tafel schwätzt ongeféier 120 Sproochen, dorënner Hollännesch, Flämesch, Piroten a Klingonesch. Näischt dovun kascht eppes, a keen probéiert dir et ze verkafen.","AI-gile ass e klengt, perséinlecht Projet, keng Firma. De Rich wollt e puer KI-Programméierprojete bedreien, ouni all App opzemaachen, fir no all ze kucken, also hunn hien an d'Agenten eng Tafel dofir gebaut an duerno mat där Tafel de Rescht vun hirem Selwer. Si ass an der zouener Pre-Alpha, dat heescht, si funktionéiert, meeschtens, fir eng Handvoll Frënn. Et gëtt keng Präisssäit, keen Newsletter a kee Wuesstemsplang. Wann et nëtzlech kléngt, kanns du froen, ob s du et probéiere kanns, wann et e bësse méi opgeet."]},{"n":144,"texts":["AI-gile ass eng Kanban-Tafel fir ee Mënsch a ganz vill KI-Agenten. Si leeft op dengem eegene Computer a ass komplett gratis. Du setz Projeten un, an all Projet kritt e Lead an e klengt Team. Du schwätz mam Lead, ongeféier wéi bei Discord, a beschreifs eng Iddi; de Lead mécht Kaarten an e Plang dorausser a waart dann, bis s du op Go dréckss. D'Team schafft d'Kaarten no Prioritéit of, mat enger einfacher Kommandozeil, déi fir Sproochmodeller gemaach ass. Ier eppes bei dech zeréckkënnt, geet en KI-Tester d'Schrëtt an enger Kopie vun der App duerch a mécht e Screenshot derbäi. Fäerdeg Aarbecht landet an dengem Stapel, mat de geännerten Dateien an dem Ënnerscheed. Du hëlls se un, oder du léiss e Kommentar, an d'Team erwächt a probéiert et nach eng Kéier. Nëmmen du kanns eng Kaart op Done réckelen. Alles dat leeft op dengem Computer, ouni Konten, ouni Tracker an ouni Cookien.","E Dag mat AI-gile, ongeféier. Owes léiss du e puer Kommentarer: dëse Knäppchen ass um falsche Plaz, déi Lëscht soll sortéiert sinn, kéinte mir en donkelen Design hunn. Du gees schlofen. D'Agenten liesen d'Kommentarer, maache d'Ännerungen, testen se a ginn se dir zeréck. Wann Ze maachen eidel gëtt, fëllt d'Nuechtwuecht et aus dem Backlog mat Kaarten, déi keng Äntwert vun dir brauchen. Moies ass do ee kuerze Stapel: e puer Froen an e puer Saachen zum Probéieren, jidd mat Schrëtt, déi e schläfrege Mënsch kann nogoen, an engem Screenshot, dee weist, datt et funktionéiert. Du klicks dech duerch, hëlls dat Gutt un a schéckss de Rescht zeréck. En Token-Zieler weist, wat dat alles gebraucht huet, an de No Token Mode ass fir schmuel Wochen do. Dann hues du Fréistuck, wou d'Agenten nach net kënne hëllefen. An der Zäit schaffe se virun, an du hues ëmmer dat lescht Wuert.","Als Éischt, wat AI-gile net ass. Et ass kee Startup, et ass net ze verkafen, a keen sammelt deng Daten. Et ass eng gratis Tafel, déi op dengem Computer leeft, ouni Konten, ouni Tracker an ouni Cookien. Wat et ass: eng ordentlech Plaz, fir all KI-Programméierprojet op eemol ze gesinn, mat engem Team vun Agenten, dat d'Kaarten ofschafft, an dir, deen d'Decisiounen trëfft. Et fält verwandte Kaarten zesummen, flécket duerchenee Titelen a passt op, datt de Code schlank bleift. Et schwätzt ongeféier 120 Sproochen, vum Hollännesche a Flämesche bis zu Piroten a Klingonesch. Frënn kënnen sech schreiwen, privat a verschlësselt. Et gouf vum Rich a ganz villen gedëlleg Agenten gebaut, meeschtens mat sech selwer. Et ass an der zouener Pre-Alpha, dofir ass et op e puer Plazen rau. Wann et nom Spaass kléngt, frot léif, a vläicht kënns du fréi eran."]}],"quips":{"1":"Ee Wuert. Mutteg. Vläicht ze mutteg.","3":"Dräi Wierder. Elo schonn éierlecher wéi déi meescht Produktsäiten.","8":"Aacht Wierder. Ëmmer nach méi kuerz wéi e Stand-up.","21":"D'Längte sinn iwwregens Story Points. Natierlech sinn et dat.","55":"Fënnefafofzeg Wierder. Zwou Kaarten si fäerdeg ginn, während s du dat gelies hues.","144":"Dat ass déi laang. Et gëtt keng 233. D'Agenten sinn schlofe gaang."}},"timeline":{"first-idea.name":"Déi éischt Iddi","first-idea.line":"Dat allereschte Gespréich, ier et iwwerhaapt Code gouf.","first-board.name":"Déi éischt Tafel","first-board.line":"Eng Tafel, déi hiren eegene Bau verfollegt: Kaarten, Kolonnen, Zéien an Ofleeën, Projeten.","team-roles.name":"Team a Rollen","team-roles.line":"Agent-Profiler, Team-Virlagen, Raim a wien wat mécht.","install.name":"Installatioun a Versiounen","install.line":"E Zip, deen e Frënd installéiere kann, Selwer-Updates, Kanäl an Zeréckrollen.","usage-saver.name":"Verbrauchsspuerer","usage-saver.line":"Moosse, wat d'Lafe kaschten, de Code schlank halen, däi Limit schounen.","friends.name":"Frënn a Deelen","friends.line":"Privat DMs, e verschlësselte Relay, Invitatiounen, Rollen a gedeelte Projeten.","languages.name":"Sproochen","languages.line":"All Bildschierm-Text an enger Sproochdatei, mat Hollännesch a Flämesch als Éischt.","ai-tester.name":"KI-Tester","ai-tester.line":"E Tester kontrolléiert all Iwwergab als Éischt a weist, wat en gesinn huet.","website.name":"D'Websäit","website.line":"aigile.lol, den Teaser an dës Zäitleescht.","streaming.name":"Chat a Streaming","streaming.line":"Discord, Twitch, OBS, Streamer-Modus, GIFs an Emojien.","no-ai.name":"Editioun ouni KI","no-ai.line":"Eng Tafel fir Leit, déi ouni KI programméieren, an ëffentlech Tafelen.","night-watch.name":"Nuechtwuecht","night-watch.line":"E Wuechter an e Scrum Master halen d'Teams um Rees, während s du schléifs.","p-more.name":"Alles anescht","p-more.line":"Méi kleng Iddien, déi nach drun sinn.","p-android.name":"Telefon an Android","p-android.line":"Erreech deng Tafel vum Telefon aus, duerno mat enger eegener Android-App.","p-release.name":"Alpha a méi wäit","p-release.line":"Zouen Alpha, déi live Säit, dunn Beta.","p-languages.name":"Méi Sproochen","p-languages.line":"Méi wéi honnert Sproochen an en Immersiounsmodus fir Léierend.","p-engines.name":"Méi KI-Motoren","p-engines.line":"Wiel Claude, Codex oder Gemini pro Agent.","p-pro.name":"Professionell Praxis","p-pro.line":"Risiko-Etiketten, Merge-Paarten, Incident-Kaarten a Leitplanken.","p-self.name":"Op dech oppassen","p-self.line":"Midd-Modus, Self-Care-Erënnerungen a 4:20.","p-servers.name":"Serveren a Wuesstem","p-servers.line":"Global Serveroptiounen, Rollen a Planung fir de Wuesstem.","p-livestream.name":"Streaming-Extrae","p-livestream.line":"Twitch-Chat, eege Emojien an eng ëffentlech Live-Usiicht."},"words":{"button":"📖 Entwécklerwierder","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"E Wuert sichen…","none":"Kee Wuert passt dozou.","close":"Zoumaachen","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Den Dossier vum Projet mam Code a senger ganzer Geschicht vu Commits, meeschtens och op GitHub gehal.","also":["Repository"]},{"id":"branch","g":"build","word":"Branch","text":"Eng getrennte Linn vun Aarbecht am Code, fir Ännerunge kënne ze maachen, ouni d'Haaptversioun unzefaassen.","also":["Branches"]},{"id":"commit","g":"build","word":"Commit","text":"E gespäichert Snapshot vum Code, mat enger kuerzer Notiz, wat sech geännert huet. Du kanns ëmmer op een zréckgoen.","also":["Commits"]},{"id":"push","g":"build","word":"Push","text":"Gespäichert Snapshots (Commits) vun dësem Computer op GitHub eropschécken, fir datt se gesécher a gedeelt sinn."},{"id":"merge","g":"build","word":"Merge","text":"D'Ännerunge vun engem Branch zréck an d'Haaptversioun zesummeféieren."},{"id":"pr","g":"build","word":"Pull Request","text":"Froen, datt d'Ännerunge vun engem Branch kontrolléiert an an d'Haaptversioun gemergt ginn.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"De Code opraumen, ouni dass sech ännert, wat e mécht: méi kleng Dateien, méi kloer Nimm, manner Widderhuelung."},{"id":"bug","g":"build","word":"Bug","text":"Eppes, wat net esou funktionéiert, wéi et sollt.","also":["Bugs"]},{"id":"test","g":"build","word":"Test","text":"E fäerdegt Stéck Aarbecht ausprobéieren, fir ze kucken, ob et mécht, wat gefrot gouf, ier s du et akzeptéiers.","also":["Tester","Testen","testen"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Eng nei Versioun live setzen, zum Beispill op e Server, wou d'Leit se notzen."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Iddien an Aarbecht, déi nach net ageplangt sinn. Do gëtt näischt gemaach, bis et op Ze maachen geréckelt gëtt."},{"id":"sprint","g":"team","word":"Sprint","text":"E kuerzen Zäitraum vun Aarbecht (dacks eng Woch oder zwou) mat engem ofgemaachte Set vu Kaarten, déi fäerdeg solle ginn.","also":["Sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"E séiere Check-in: wat all Teammember gemaach huet, wat e loossgeet, a wat en ophält.","also":["Standup","Stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"E Board mat Kolonnen (Ze maachen, Amgaang, Fäerdeg), wou d'Kaarte vu lénks no riets réckelen, wéi d'Aarbecht geschitt."},{"id":"wip","g":"team","word":"WIP-Limit","text":"Work in progress: déi meescht Kaarten, déi eng Kolonn halen soll, fir datt d'Team d'Saache fäerdeg mécht, éier et méi ufänkt.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Eng KI, déi eleng un enger Aufgab schafft: liest de Code, mécht Ännerungen, féiert Kontrolle aus a mellt sech zeréck.","also":["Agenten","Agents"]},{"id":"token","g":"team","word":"Token","text":"D'Eenheet, an där d'KI-Notzung gezielt gëtt: ongeféier e puer Buschtawen Text, gelies oder geschriwwen. Manner Tokens, méi bleift vun dengem Plang iwwreg.","also":["Tokens"]},{"id":"hook","g":"team","word":"Hook","text":"E klenge Kommando, deen zu engem festgeluechte Moment vu sech aus leeft, z. B. wann eng KI-Sessioun ufänkt, fir datt d'Team deng Kommentarer héiert.","also":["Hooks"]}]}};
